\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{siunitx}
\sisetup{per-mode=symbol}

\title{Block C Irrigation and Spray Log --- 2025 Season}
\author{Vineyard Operations}
\date{October 2025}

\begin{document}
\maketitle

\section{Block details}
Block C covers 3.2 ha of north-facing rows planted in 2011.
The soil is a gravel loam over clay, and the drip line runs
emitters rated at \SI{850}{\milli\litre} per hour at nominal
pressure. The block is divided into four irrigation sectors
that can be valved independently from the shed.

\section{Irrigation schedule}
From fruit set to veraison the vines received
\SI{2.4}{\litre} per vine per event, twice weekly, with the
interval shortened during the August heat spell. Cumulative
applied water for the season reached \SI{35}{\milli\metre},
about a quarter below the ten-year mean, which kept canopy
vigour in check without measurable stress.

\section{Spray log}
Sulphur applications ran at fortnight intervals through
June and July. Spray pressure at the boom was held at
180 \si{\kilo\pascal}, and the wettable sulphur was mixed at
40 \si{\milli\gram\per\litre} of tank volume. No phytotoxicity
was observed on the treated rows, and coverage was checked
with water-sensitive cards at every second pass.

\section{Harvest}
Picking ran over four mornings in the second week of
September. Yields averaged
\SI{1.8e3}{\kilo\gram\per\hectare}, in line with the block
average, and fruit arrived at the weighbridge cool enough
that no sulphur additions were needed at receival.

\section{Notes for next season}
The sector valves on the lower rows are weeping and should
be replaced before budburst. The schedule above is otherwise
worth repeating unchanged.
\end{document}

